function normKey(s: string): string {
  return s
    .toLowerCase()
    .replace(/\([^)]*\)/g, '')                       // drop (250 ml) etc.
    .replace(/\b(cold[- ]?pressed|fresh|organic|raw|pure|natural|farm|nattu|naatu)\b/g, '')
    .replace(/[^a-z0-9]/g, '')
    .replace(/(250ml|500ml|1l|1litre|1000ml|250g|500g|1kg|5kg|1000g|whole|split|pack)$/,'');
}

export function resolveImageByName(name?: string): string | null {
  if (!name) return null;
  const k = normKey(name);
  if (!k) return null;
  if (PRODUCT_IMAGE_BY_NAME[k]) return PRODUCT_IMAGE_BY_NAME[k] as string;
  // loose contains match — longest key wins to avoid "ground" catching everything
  let best: string | null = null;
  let bestLen = 0;
  for (const key of Object.keys(PRODUCT_IMAGE_BY_NAME)) {
    if (key.length < 5) continue;
    if ((k.includes(key) || key.includes(k)) && key.length > bestLen) {
      best = PRODUCT_IMAGE_BY_NAME[key] as string;
      bestLen = key.length;
    }
  }
  return best;
}
